#!/usr/bin/env python3
"""Validate paired GeoLife views generated by the published episode operator."""

from __future__ import annotations

import argparse
import hashlib
import json
import sys
from pathlib import Path

import numpy as np

REPO_ROOT = Path(__file__).resolve().parents[1]
if str(REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(REPO_ROOT))

from tmi.data_preprocess.variable_sampling import (
    DEFAULT_CONDITIONS,
    apply_condition,
)


SPLITS = ("train", "val", "test")
METADATA = ("labels", "user_ids", "source_ids", "pair_ids")


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def load(root: Path, condition: str, split: str, suffix: str):
    return np.load(
        root / condition / f"{split}_{suffix}.npy", allow_pickle=True
    )


def interval_stats(trajectories) -> dict:
    intervals = np.concatenate([
        np.diff(np.asarray(trajectory, dtype=float)[:, 0])
        for trajectory in trajectories if len(trajectory) > 1
    ])
    lengths = np.asarray([len(trajectory) for trajectory in trajectories])
    return {
        "samples": int(len(trajectories)),
        "points_mean": float(lengths.mean()),
        "points_median": float(np.median(lengths)),
        "interval_mean_seconds": float(intervals.mean()),
        "interval_median_seconds": float(np.median(intervals)),
        "interval_std_seconds": float(intervals.std()),
        "interval_min_seconds": float(intervals.min()),
        "interval_max_seconds": float(intervals.max()),
    }


def validate(args) -> dict:
    root = args.views_root.resolve()
    payload = {
        "protocol": "geolife-published-episode-sampling-v2",
        "status": "PASSED",
        "checks": {
            "user_disjoint": True,
            "metadata_aligned": True,
            "real_points_only": True,
            "operator_reproducible": True,
            "fixed_point_density_order": True,
            "variable_intervals_present": True,
        },
        "splits": {},
        "file_sha256": {},
        "legacy_fixed_view_match": {},
    }

    split_users = {}
    for split in SPLITS:
        dense = load(root, "fixed_5s", split, "trjs")
        pair_ids = load(root, "fixed_5s", split, "pair_ids")
        split_users[split] = set(map(
            int, load(root, "fixed_5s", split, "user_ids")
        ))

        reference_metadata = {
            suffix: load(root, "fixed_5s", split, suffix)
            for suffix in METADATA
        }
        condition_stats = {}
        for condition in DEFAULT_CONDITIONS:
            trajectories = load(root, condition, split, "trjs")
            if len(trajectories) != len(dense):
                raise AssertionError(
                    f"{split}/{condition}: unpaired sample count"
                )
            for suffix, expected in reference_metadata.items():
                actual = load(root, condition, split, suffix)
                if not np.array_equal(actual, expected):
                    raise AssertionError(
                        f"{split}/{condition}: {suffix} not aligned"
                    )

            for index, (canonical, actual, pair_id) in enumerate(
                    zip(dense, trajectories, pair_ids)):
                expected = apply_condition(
                    canonical, condition, args.seed, str(pair_id)
                )
                if not np.array_equal(np.asarray(actual), expected):
                    raise AssertionError(
                        f"{split}/{condition}/{index}: operator mismatch"
                    )
            condition_stats[condition] = interval_stats(trajectories)

            path = root / condition / f"{split}_trjs.npy"
            payload["file_sha256"][
                f"{condition}/{split}_trjs.npy"
            ] = sha256(path)

            if args.legacy_root and condition.startswith("fixed_"):
                legacy_path = (
                    args.legacy_root.resolve() / condition /
                    f"{split}_trjs.npy"
                )
                if legacy_path.is_file():
                    matches = sha256(path) == sha256(legacy_path)
                    payload["legacy_fixed_view_match"][
                        f"{condition}/{split}"
                    ] = matches

        means = [
            condition_stats[name]["points_mean"]
            for name in ("fixed_5s", "fixed_30s", "fixed_60s")
        ]
        if not means[0] > means[1] > means[2]:
            raise AssertionError(f"{split}: point density is not ordered")
        if condition_stats["variable_5_60s"]["interval_std_seconds"] <= 0:
            raise AssertionError(f"{split}: variable view has fixed intervals")

        payload["splits"][split] = {
            "user_count": len(split_users[split]),
            "condition_stats": condition_stats,
        }

    for left_index, left in enumerate(SPLITS):
        for right in SPLITS[left_index + 1:]:
            overlap = split_users[left] & split_users[right]
            if overlap:
                raise AssertionError(
                    f"{left}/{right}: overlapping users {sorted(overlap)}"
                )
    return payload


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--views-root", type=Path, required=True)
    parser.add_argument("--legacy-root", type=Path)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--seed", type=int, default=42)
    args = parser.parse_args()

    payload = validate(args)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(
        json.dumps(payload, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    print("Published sampling dataset validation: PASSED")
    print(f"Saved: {args.output}")


if __name__ == "__main__":
    main()
